/**
 * The deterministic stages. There are three moments for rules around the model:
 *
 *   prepare   before the model: the structural commands that are exact and have side effects
 *             ("press enter"), or that are pure layout ("new line", "question mark");
 *   basic     instead of the model: the rule-based fallback when there is no model, the model
 *             failed, or the user turned smart formatting off;
 *   finish    after either: dictionary spellings, spacing, destination finishing, trailing space.
 *
 * Snippets are expanded by the client after finishing, because their content may depend on the
 * device (clipboard, local time).
 */

export interface PreparedTranscript {
  text: string
  pressEnter: boolean
  stages: string[]
}

export function prepareTranscript(raw: string): PreparedTranscript {
  const stages: string[] = []
  // A line break in the recognizer's own text is never something the speaker dictated: speech
  // models break lines at pauses or segment boundaries. Dictated breaks arrive as words ("new
  // line", "new paragraph") and are applied below, so raw breaks become spaces here.
  let text = normalizeWhitespace(raw.replace(/[ \t]*[\r\n]+[ \t]*/g, ' '))
  const enter = extractPressEnter(text)
  if (enter.pressEnter) {
    stages.push('press-enter')
    text = enter.text
  }
  const step = (name: string, fn: (s: string) => string): void => {
    const next = fn(text)
    if (next !== text) stages.push(name)
    text = next
  }
  // A phrase the speech model wrote over and over ("…the keyboard. Step 5 shows the keyboard.").
  step('loops', collapseLoops)
  step('line-commands', applyLineCommands)
  step('literal-punctuation', applyLiteralPunctuation)
  // Before the model sees it too: a period at a pause where no sentence can end.
  step('pause-stops', joinPauseStops)
  return { text: normalizeWhitespace(text), pressEnter: enter.pressEnter, stages }
}

export interface BasicCleanupOptions {
  dictionary: readonly DictionaryTerm[]
}

/** Rule-based tidying of a prepared transcript: what "light" formatting and every fallback insert. */
export function basicCleanup(
  prepared: string,
  opts: BasicCleanupOptions
): { text: string; stages: string[] } {
  const stages: string[] = []
  let text = prepared
  const step = (name: string, fn: (s: string) => string): void => {
    const next = fn(text)
    if (next !== text) stages.push(name)
    text = next
  }
  step('scratch-that', applyScratchThat)
  step('quotes', applySpokenQuotes)
  step('fillers', (s) => removeFillers(s))
  step('dictionary', (s) => applyDictionary(s, opts.dictionary))
  step('punctuation', fixPunctuationSpacing)
  step('capitalize', capitalizeSentences)
  return { text: normalizeWhitespace(text), stages }
}

export interface FinishOptions {
  category: AppCategory
  dictionary: readonly DictionaryTerm[]
  trailingSpace: boolean
  snippets?: readonly Snippet[]
  snippetContext?: SnippetContext
  /** The profile's casing; `lowercase` lowers sentence starts before snippets expand. */
  casing?: Casing
  /** Text before the cursor, when the platform can read it: the dictation continues it. */
  precedingText?: string
}

export interface Finished {
  text: string
  empty: boolean
  stages: string[]
  snippetsExpanded: string[]
}

/** Belt and braces after the model (or the fallback): the parts that must be exact. */
export function finish(text: string, opts: FinishOptions): Finished {
  const stages: string[] = []
  let out = normalizeWhitespace(text)
  const dict = applyDictionary(out, opts.dictionary)
  if (dict !== out) stages.push('dictionary')
  out = fixPunctuationSpacing(dict)
  if (opts.category === 'terminal') {
    // A command stays on one line and never ends in prose punctuation.
    const one = out
      .replace(/\s*\n+\s*/g, ' ')
      .trim()
      .replace(/\.+$/, '')
    if (one !== out) stages.push('terminal')
    out = one
  }
  if (opts.category !== 'terminal' && opts.category !== 'code') {
    // Points counted out loud are a numbered list, whether or not a model formatted the text.
    const listed = numberCuedSentences(out)
    if (listed !== out) stages.push('list')
    out = listed
  }
  const cased = applyCasing(
    out,
    opts.casing,
    opts.category,
    opts.dictionary.map((d) => d.word)
  )
  if (cased !== out) stages.push('casing')
  out = cased
  // A sentence that starts in lower case after a period (a seam between pieces, a model that
  // lowered it) gets its capital, whichever path the text took. Not for a lower-case profile.
  if (opts.casing !== 'lowercase') {
    const up = repairCase('', out, { category: opts.category, precedingText: opts.precedingText })
    if (up !== out) stages.push('sentence-case')
    out = up
  }
  if (opts.category !== 'code' && opts.category !== 'terminal') {
    const joined = joinRunningSentences(out)
    if (joined !== out) stages.push('rejoin')
    out = joined
  }
  const continued = continueFrom(out, opts.precedingText, opts.category)
  if (continued !== out) stages.push('continue')
  out = continued
  const snippets = expandSnippets(out, opts.snippets ?? [], opts.snippetContext)
  if (snippets.expanded.length) stages.push('snippets')
  out = normalizeWhitespace(snippets.text)
  if (continued.startsWith(' ') && !out.startsWith(' ')) out = ` ${out}`
  const empty = !isMeaningful(out)
  if (!empty) out = applyTrailing(out, opts.trailingSpace && !out.endsWith('\n'))
  return { text: empty ? '' : out, empty, stages, snippetsExpanded: snippets.expanded }
}

/**
 * A dictation that goes on from text already in the field. Mid-sentence ("I think we should|"),
 * a capital the speech model or formatter gave the first word comes off when it is an ordinary
 * word ("Probably" -> "probably"); names, "I", acronyms and words not in the common-word list keep
 * it. After a sentence end, a lower-case first word gets its capital. And when the text before
 * ends on a letter or punctuation with no space, one space goes in front, so the words do not run
 * together. Not in code or a terminal.
 */
export function continueFrom(text: string, preceding: string | undefined, category: AppCategory): string {
  if (!preceding || !text || category === 'code' || category === 'terminal') return text
  if (!preceding.trim()) return text
  const m = /^(\p{L}[\p{L}'’]*)/u.exec(text)
  let out = text
  const midSentence = /[\p{L}\p{N},;:–—-]["'”’)\]]*\s*$/u.test(preceding) && !/\n\s*$/u.test(preceding)
  const sentenceEnd = /[.!?…]["'”’)\]]*\s*$/u.test(preceding)
  if (m) {
    const w = m[1]
    const lower = w.toLowerCase()
    const isCapitalized = /^\p{Lu}\p{Ll}*(?:['’]\p{Ll}+)?$/u.test(w)
    if (midSentence && isCapitalized && w.length > 1 && !/^i['’]/i.test(w) && COMMON_WORDS.has(lower))
      out = lower + out.slice(w.length)
    else if (sentenceEnd && /^\p{Ll}/u.test(w)) out = w.charAt(0).toUpperCase() + out.slice(1)
  }
  // One space between the text before and the dictation, unless it starts with punctuation that
  // closes the word before (",", ".").
  if (/[^\s]$/u.test(preceding) && !/^[\s,.;:!?…)\]]/u.test(out)) out = ` ${out}`
  return out
}
